                "//a[contains(@href,'GoogleOAuth')]",
                "//a[contains(@class,'auth-method-button') and contains(@href,'GoogleOAuth')]",
                "(//a[contains(@class,'auth-method-button')])[1]"  # First auth button as fallback
            ]

            auth_btn = None
            for selector in selectors:
